6	// AscendC DequantSwigluQuant kernel — fused dequant(int32->fp32) + SwiGLU + per-row int8 quant
7	// Two-pass per row:
8	//   Pass 1: compute SwiGLU per tile, smooth quant, accumulate to smoothBuf, track absmax.
9	//   Pass 2: read smoothBuf per tile, quantize (div by safeScale, round, clamp, cast), write output.
10	
11	#include "kernel_operator.h"
12	
13	constexpr int32_t BUFFER_NUM = 1;
14	constexpr int32_t TILE_H = 512;
15	
16	__aicore__ inline int32_t CeilDiv(int32_t a, int32_t b)
17	{
18	    if (b == 0) { return 0; }
19	    return (a + b - 1) / b;
20	}
21	
22	template <typename T>
23	__aicore__ inline void LoadGmPad(
24	    AscendC::LocalTensor<T> &dst, AscendC::GlobalTensor<T> src, uint32_t count)
25	{
26	    AscendC::DataCopyExtParams cp{1, count * static_cast<uint32_t>(sizeof(T)), 0, 0, 0};
27	    AscendC::DataCopyPadExtParams<T> pp{true, 0, 0, static_cast<T>(0)};
28	    AscendC::DataCopyPad(dst, src, cp, pp);
29	}
30	
31	template <typename T>
32	__aicore__ inline void StoreUbPad(
33	    AscendC::GlobalTensor<T> dst, AscendC::LocalTensor<T> &src, uint32_t count)
34	{
35	    AscendC::DataCopyExtParams cp{1, count * static_cast<uint32_t>(sizeof(T)), 0, 0, 0};
36	    AscendC::DataCopyPad(dst, src, cp);
37	}
38	
39	template <typename T>
40	__aicore__ inline void LoadGmStridedE2(
41	    AscendC::LocalTensor<T> &dst, AscendC::GlobalTensor<T> src, uint32_t count)
42	{
43	    AscendC::DataCopyExtParams cp{
44	        static_cast<uint16_t>(count), static_cast<uint16_t>(sizeof(T)),
45	        static_cast<uint16_t>(2 * sizeof(T)), static_cast<uint16_t>(sizeof(T)), 0};
46	    AscendC::DataCopyPadExtParams<T> pp{true, 0, 0, static_cast<T>(0)};
47	    AscendC::DataCopyPad(dst, src, cp, pp);
48	}
49	
50	class DequantSwigluQuantKernel {
51	public:
52	    __aicore__ inline void Init(
53	        GM_ADDR x, GM_ADDR weightScale, GM_ADDR activationScale,
54	        GM_ADDR quantScale, GM_ADDR y, GM_ADDR rowScale,
55	        int32_t M, int32_t N, int32_t H,
56	        int32_t blockM, int32_t usedCoreNum, int32_t tasksPerCore,
57	        int64_t swigluMode, int64_t activateLeft,
58	        float clampLimit, float gluAlpha, float gluBeta)
59	    {
60	        M_ = M; N_ = N; H_ = H; blockM_ = blockM;
61	        usedCoreNum_ = usedCoreNum; tasksPerCore_ = tasksPerCore;
62	        swigluMode_ = static_cast<int32_t>(swigluMode);
63	        activateLeft_ = static_cast<int32_t>(activateLeft);
64	        clampLimit_ = clampLimit;
65	        gluAlpha_ = gluAlpha; gluBeta_ = gluBeta;
66	        inv127_ = 1.0f / 127.0f;
67	        vecNum_ = AscendC::GetSubBlockNum();
68	
69	        xGM_.SetGlobalBuffer(reinterpret_cast<__gm__ int32_t *>(x), static_cast<uint64_t>(M) * N);
70	        wsGM_.SetGlobalBuffer(reinterpret_cast<__gm__ float *>(weightScale), static_cast<uint64_t>(1) * N);
71	        asGM_.SetGlobalBuffer(reinterpret_cast<__gm__ float *>(activationScale), static_cast<uint64_t>(M));
72	        qsGM_.SetGlobalBuffer(reinterpret_cast<__gm__ float *>(quantScale), static_cast<uint64_t>(1) * H);
73	        yGM_.SetGlobalBuffer(reinterpret_cast<__gm__ int8_t *>(y), static_cast<uint64_t>(M) * H);
74	        rsGM_.SetGlobalBuffer(reinterpret_cast<__gm__ float *>(rowScale), static_cast<uint64_t>(M));
75	
76	        if ASCEND_IS_AIV { InitBuffers(); }
77	    }
78	
79	    __aicore__ inline void Process()
80	    {
81	        if ASCEND_IS_AIV {
82	            int32_t ci = AscendC::GetBlockIdx() / vecNum_;
83	            int32_t si = AscendC::GetSubBlockIdx();
84	            int32_t sr = blockM_ / vecNum_;
85	            int32_t mn = CeilDiv(M_, blockM_);
86	            for (int32_t li = 0; li < tasksPerCore_; ++li) {
87	                int32_t bx = ci * tasksPerCore_ + li;
88	                if (bx >= mn) continue;
89	                for (int32_t r = 0; r < sr; ++r) {
90	                    int32_t ri = bx * blockM_ + si * sr + r;
91	                    if (ri >= M_) continue;
92	                    ProcessRow(ri);
93	                }
94	            }
95	        }
96	    }
97	
98	private:
99	    __aicore__ inline void InitBuffers()
100	    {
101	        pipe_.InitBuffer(reduceTmp_, TILE_H * sizeof(float));
102	        pipe_.InitBuffer(scalarBuf_, sizeof(float));
103	        pipe_.InitBuffer(smoothBuf_, H_ * sizeof(float));
104	        pipe_.InitBuffer(xInQueue_, BUFFER_NUM, 2 * TILE_H * sizeof(int32_t));
105	        pipe_.InitBuffer(wsInQueue_, BUFFER_NUM, 2 * TILE_H * sizeof(float));
106	        pipe_.InitBuffer(fullDeq_, 2 * TILE_H * sizeof(float));
107	        pipe_.InitBuffer(yOutQueue_, BUFFER_NUM, TILE_H * sizeof(int8_t));
108	        pipe_.InitBuffer(dqFront_, TILE_H * sizeof(float));
109	        pipe_.InitBuffer(dqBack_, TILE_H * sizeof(float));
110	        pipe_.InitBuffer(swBuf_, TILE_H * sizeof(float));
111	        pipe_.InitBuffer(sigBuf_, TILE_H * sizeof(float));
112	        pipe_.InitBuffer(tmpBuf_, TILE_H * sizeof(float));
113	        pipe_.InitBuffer(qsBuf_, TILE_H * sizeof(float));
114	    }
115	
116	    // ===================================================================
117	    // Two-pass per row
118	    // ===================================================================
119	    __aicore__ inline void ProcessRow(int32_t rowIdx)
120	    {
121	        // Load activation_scale
122	        AscendC::LocalTensor<float> sb = scalarBuf_.Get<float>();
123	        {
124	            AscendC::DataCopyExtParams cp{1, sizeof(float), 0, 0, 0};
125	            AscendC::DataCopyPadExtParams<float> pp{false, 0, 0, 0.0f};
126	            AscendC::DataCopyPad(sb, asGM_[static_cast<uint64_t>(rowIdx)], cp, pp);
127	        }
128	        AscendC::PipeBarrier<PIPE_MTE2>();
129	        AscendC::PipeBarrier<PIPE_ALL>();
130	        float asVal = sb.GetValue(0);
131	
132	        // === Pass 1: compute SwiGLU + smooth quant, accumulate, track absmax ===
133	        float absmax = 0.0f;
134	        int32_t hTiles = CeilDiv(H_, TILE_H);
135	
136	        for (int32_t ht = 0; ht < hTiles; ++ht) {
137	            int32_t os = ht * TILE_H;
138	            int32_t co = (os + TILE_H <= H_) ? TILE_H : (H_ - os);
139	
140	            ComputeSwiGLU(rowIdx, os, co, asVal);
141	
142	            // Smooth quant: sw * qs
143	            AscendC::LocalTensor<float> sw = swBuf_.Get<float>();
144	            AscendC::LocalTensor<float> qs = qsBuf_.Get<float>();
145	            LoadGmPad(qs, qsGM_[static_cast<uint64_t>(os)], static_cast<uint32_t>(co));
146	            AscendC::PipeBarrier<PIPE_MTE2>();
147	            AscendC::PipeBarrier<PIPE_ALL>();
148	            AscendC::Mul(sw, sw, qs, co);
149	            AscendC::PipeBarrier<PIPE_V>();
150	
151	            // Accumulate into smoothBuf
152	            AscendC::LocalTensor<float> smDst = smoothBuf_.Get<float>();
153	            AscendC::DataCopy(smDst[os], sw, co);
154	            AscendC::PipeBarrier<PIPE_MTE2>();
155	            AscendC::PipeBarrier<PIPE_ALL>();
156	
157	            // Track absmax
158	            AscendC::LocalTensor<float> ab = tmpBuf_.Get<float>();
159	            AscendC::Abs(ab, sw, co);
160	            AscendC::PipeBarrier<PIPE_V>();
161	
162	            AscendC::LocalTensor<float> rb = reduceTmp_.Get<float>();
163	            AscendC::LocalTensor<float> am = scalarBuf_.Get<float>();
164	            AscendC::ReduceMax<float>(am, ab, rb, co);
165	            AscendC::PipeBarrier<PIPE_ALL>();
166	            float tm = am.GetValue(0);
167	            if (tm > absmax) absmax = tm;
168	        }
169	
170	        // Compute scales
171	        float sc = absmax * inv127_;
172	        float ssc = (sc > 0.0f) ? sc : 1.0f;
173	        float iSc = 1.0f / ssc;
174	
175	        // Write rowScale
176	        AscendC::LocalTensor<float> rsUb = scalarBuf_.Get<float>();
177	        rsUb.SetValue(0, ssc);
178	        AscendC::PipeBarrier<PIPE_V>();
179	        AscendC::GlobalTensor<float> rsDst = rsGM_[static_cast<uint64_t>(rowIdx)];
180	        AscendC::DataCopyExtParams rsCp{1, sizeof(float), 0, 0, 0};
181	        AscendC::DataCopyPad(rsDst, rsUb, rsCp);
182	        AscendC::PipeBarrier<PIPE_MTE2>();
183	        AscendC::PipeBarrier<PIPE_ALL>();
184	
185	        // === Pass 2: read smoothBuf, quantize, write output ===
186	        for (int32_t ht = 0; ht < hTiles; ++ht) {
187	            int32_t os = ht * TILE_H;
188	            int32_t co = (os + TILE_H <= H_) ? TILE_H : (H_ - os);
189	
190	            // Quantize from smoothBuf: read tile into swBuf_
191	            AscendC::LocalTensor<float> sm = swBuf_.Get<float>();
192	            AscendC::LocalTensor<float> smSrc = smoothBuf_.Get<float>();
193	            AscendC::DataCopy(sm, smSrc[os], co);
194	            AscendC::PipeBarrier<PIPE_MTE2>();
195	            AscendC::PipeBarrier<PIPE_ALL>();
196	
197	            // * invScale → round → clamp → cast to int8
198	            AscendC::Muls(sm, sm, iSc, co);
199	            AscendC::PipeBarrier<PIPE_V>();
200	            AscendC::Cast(sm, sm, AscendC::RoundMode::CAST_ROUND, co);
201	            AscendC::PipeBarrier<PIPE_V>();
202	
203	            // Clamp: use dqFront_ as clamp buffer (different from sm=swBuf_)
204	            AscendC::LocalTensor<float> cl = dqFront_.Get<float>();
205	            AscendC::Mins(cl, sm, 127.0f, co);
206	            AscendC::PipeBarrier<PIPE_V>();
207	            AscendC::Maxs(cl, cl, -128.0f, co);
208	            AscendC::PipeBarrier<PIPE_V>();
209	
210	            // Cast float→half→int8
211	            AscendC::LocalTensor<half> htH = dqBack_.Get<half>();
212	            AscendC::Cast(htH, cl, AscendC::RoundMode::CAST_NONE, co);
213	            AscendC::PipeBarrier<PIPE_V>();
214	
215	            AscendC::LocalTensor<int8_t> yo = yOutQueue_.AllocTensor<int8_t>();
216	            AscendC::Cast(yo, htH, AscendC::RoundMode::CAST_NONE, co);
217	            AscendC::PipeBarrier<PIPE_V>();
218	            yOutQueue_.EnQue(yo);
219	
220	            yo = yOutQueue_.DeQue<int8_t>();
221	            AscendC::GlobalTensor<int8_t> yDst = yGM_[static_cast<uint64_t>(rowIdx) * H_ + os];
222	            StoreUbPad(yDst, yo, static_cast<uint32_t>(co));
223	            yOutQueue_.FreeTensor(yo);
224	            AscendC::PipeBarrier<PIPE_MTE2>();
225	            AscendC::PipeBarrier<PIPE_ALL>();
226	        }
227	    }
228	
229	    // ===================================================================
230	    // SwiGLU computation (result in swBuf_)
231	    // ===================================================================
232	    __aicore__ inline void ComputeSwiGLU(
233	        int32_t rowIdx, int32_t outStart, int32_t curOut, float asVal)
234	    {
235	        if (swigluMode_ == 0) {
236	            // Mode 0: halves split + Swish
237	            // front = dequant(x[row, os:os+co]), back = dequant(x[row, H+os:H+os+co])
238	            DequantHalf(rowIdx, outStart, 0, curOut, asVal, dqFront_);
239	            DequantHalf(rowIdx, outStart, H_, curOut, asVal, dqBack_);
240	
241	            AscendC::LocalTensor<float> glu, lin;
242	            if (activateLeft_) {
243	                glu = dqFront_.Get<float>(); lin = dqBack_.Get<float>();
244	            } else {
245	                glu = dqBack_.Get<float>(); lin = dqFront_.Get<float>();
246	            }
247	
248	            // sigmoid(glu) = 1/(1+exp(-glu))
249	            AscendC::LocalTensor<float> sg = sigBuf_.Get<float>();
250	            AscendC::Muls(sg, glu, -1.0f, curOut);  AscendC::PipeBarrier<PIPE_V>();
251	            AscendC::Exp(sg, sg, curOut);            AscendC::PipeBarrier<PIPE_V>();
252	            AscendC::Adds(sg, sg, 1.0f, curOut);    AscendC::PipeBarrier<PIPE_V>();
253	            AscendC::Reciprocal(sg, sg, curOut);     AscendC::PipeBarrier<PIPE_V>();
254	
255	            // sw = lin * glu * sigmoid
256	            AscendC::LocalTensor<float> sw = swBuf_.Get<float>();
257	            AscendC::Mul(sw, glu, sg, curOut);  AscendC::PipeBarrier<PIPE_V>();
258	            AscendC::Mul(sw, sw, lin, curOut);  AscendC::PipeBarrier<PIPE_V>();
259	        } else {
260	            // Mode 1: even/odd split + gpt-oss
261	            int32_t is = outStart * 2;
262	            DequantStrided(rowIdx, is, curOut, asVal, dqFront_);
263	            DequantStrided(rowIdx, is + 1, curOut, asVal, dqBack_);
264	
265	            AscendC::LocalTensor<float> glu = dqFront_.Get<float>();
266	            AscendC::LocalTensor<float> lin = dqBack_.Get<float>();
267	
268	            // glu_c = min(glu, L)
269	            AscendC::LocalTensor<float> gc = tmpBuf_.Get<float>();
270	            AscendC::Mins(gc, glu, clampLimit_, curOut);  AscendC::PipeBarrier<PIPE_V>();
271	
272	            // lin_c = clamp(lin, -L, L)
273	            AscendC::Mins(lin, lin, clampLimit_, curOut);  AscendC::PipeBarrier<PIPE_V>();
274	            AscendC::Maxs(lin, lin, -clampLimit_, curOut); AscendC::PipeBarrier<PIPE_V>();
275	
276	            // sigmoid(alpha * glu_c)
277	            AscendC::LocalTensor<float> sg = sigBuf_.Get<float>();
278	            AscendC::Muls(sg, gc, gluAlpha_, curOut);  AscendC::PipeBarrier<PIPE_V>();
279	            AscendC::Muls(sg, sg, -1.0f, curOut);      AscendC::PipeBarrier<PIPE_V>();
280	            AscendC::Exp(sg, sg, curOut);               AscendC::PipeBarrier<PIPE_V>();
281	            AscendC::Adds(sg, sg, 1.0f, curOut);       AscendC::PipeBarrier<PIPE_V>();
282	            AscendC::Reciprocal(sg, sg, curOut);         AscendC::PipeBarrier<PIPE_V>();
283	
284	            // lin_c + beta
285	            AscendC::Adds(lin, lin, gluBeta_, curOut);  AscendC::PipeBarrier<PIPE_V>();
286	
287	            // sw = glu_c * sigmoid * (lin_c + beta)
288	            AscendC::LocalTensor<float> sw = swBuf_.Get<float>();
289	            AscendC::Mul(sw, gc, sg, curOut);   AscendC::PipeBarrier<PIPE_V>();
290	            AscendC::Mul(sw, sw, lin, curOut);  AscendC::PipeBarrier<PIPE_V>();
291	        }
292	    }
293	
294	    // Dequant contiguous half-tile: int32 load → Cast → Mul(ws) → Muls(as)
295	    __aicore__ inline void DequantHalf(
296	        int32_t rowIdx, int32_t outStart, int32_t colOffset,
297	        int32_t curOut, float asVal,
298	        AscendC::TBuf<AscendC::TPosition::VECCALC> &dqBuf)
299	    {
300	        AscendC::LocalTensor<int32_t> xi = xInQueue_.AllocTensor<int32_t>();
301	        LoadGmPad(xi, xGM_[static_cast<uint64_t>(rowIdx) * N_ + colOffset + outStart],
302	                  static_cast<uint32_t>(curOut));
303	        xInQueue_.EnQue(xi);
304	        xi = xInQueue_.DeQue<int32_t>();
305	
306	        AscendC::LocalTensor<float> wi = wsInQueue_.AllocTensor<float>();
307	        LoadGmPad(wi, wsGM_[static_cast<uint64_t>(colOffset + outStart)],
308	                  static_cast<uint32_t>(curOut));
309	        wsInQueue_.EnQue(wi);
310	        wi = wsInQueue_.DeQue<float>();
311	
312	        AscendC::LocalTensor<float> dq = dqBuf.Get<float>();
313	        AscendC::Cast(dq, xi, AscendC::RoundMode::CAST_NONE, curOut);
314	        AscendC::PipeBarrier<PIPE_V>();
315	        AscendC::Mul(dq, dq, wi, curOut);
316	        AscendC::PipeBarrier<PIPE_V>();
317	        AscendC::Muls(dq, dq, asVal, curOut);
318	        AscendC::PipeBarrier<PIPE_V>();
319	
320	        wsInQueue_.FreeTensor(wi);
321	        xInQueue_.FreeTensor(xi);
322	    }
323	
324	    // Dequant strided (every 2nd element): int32 load → Cast → Mul(ws) → Muls(as)
325	    __aicore__ inline void DequantStrided(
326	        int32_t rowIdx, int32_t inStart, int32_t curOut, float asVal,
327	        AscendC::TBuf<AscendC::TPosition::VECCALC> &dqBuf)
328	    {
329	        AscendC::LocalTensor<int32_t> xi = xInQueue_.AllocTensor<int32_t>();
330	        LoadGmStridedE2(xi, xGM_[static_cast<uint64_t>(rowIdx) * N_ + inStart],
331	                        static_cast<uint32_t>(curOut));
332	        xInQueue_.EnQue(xi);
333	        xi = xInQueue_.DeQue<int32_t>();
334	
335	        AscendC::LocalTensor<float> wi = wsInQueue_.AllocTensor<float>();
336	        LoadGmStridedE2(wi, wsGM_[static_cast<uint64_t>(inStart)],
337	                        static_cast<uint32_t>(curOut));
338	        wsInQueue_.EnQue(wi);
339	        wi = wsInQueue_.DeQue<float>();
340	
341	        AscendC::LocalTensor<float> dq = dqBuf.Get<float>();
342	        AscendC::Cast(dq, xi, AscendC::RoundMode::CAST_NONE, curOut);
343	        AscendC::PipeBarrier<PIPE_V>();
344	        AscendC::Mul(dq, dq, wi, curOut);
345	        AscendC::PipeBarrier<PIPE_V>();
346	        AscendC::Muls(dq, dq, asVal, curOut);
347	        AscendC::PipeBarrier<PIPE_V>();
348	
349	        wsInQueue_.FreeTensor(wi);
350	        xInQueue_.FreeTensor(xi);
351	    }
352	
353	private:
354	    int32_t M_ = 0, N_ = 0, H_ = 0;
355	    int32_t blockM_ = 0, usedCoreNum_ = 0, tasksPerCore_ = 0;
356	    int32_t swigluMode_ = 0, activateLeft_ = 0;
357	    float clampLimit_ = 0, gluAlpha_ = 0, gluBeta_ = 0;
358	    float inv127_ = 0; int32_t vecNum_ = 0;
359	
360	    AscendC::GlobalTensor<int32_t> xGM_;
361	    AscendC::GlobalTensor<float> wsGM_, asGM_, qsGM_, rsGM_;
362	    AscendC::GlobalTensor<int8_t> yGM_;
363	
364	    AscendC::TPipe pipe_;
365	    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> xInQueue_, wsInQueue_;
366	    AscendC::TQue<AscendC::TPosition::VECOUT, BUFFER_NUM> yOutQueue_;
367	    AscendC::TBuf<AscendC::TPosition::VECCALC> reduceTmp_, scalarBuf_;
368	    AscendC::TBuf<AscendC::TPosition::VECCALC> smoothBuf_;
369	    AscendC::TBuf<AscendC::TPosition::VECCALC> dqFront_, dqBack_;
370	    AscendC::TBuf<AscendC::TPosition::VECCALC> swBuf_, sigBuf_, tmpBuf_, qsBuf_, fullDeq_;
371	};
372	
373	extern "C" __global__ __aicore__ void dequant_swiglu_quant(
374	    GM_ADDR x, GM_ADDR weightScale, GM_ADDR activationScale,
375	    GM_ADDR quantScale, GM_ADDR y, GM_ADDR rowScale,
376	    int32_t M, int32_t N, int32_t H,
377	    int32_t blockM, int32_t usedCoreNum, int32_t tasksPerCore,
378	    int64_t swigluMode, int64_t activateLeft,
379	    float clampLimit, float gluAlpha, float gluBeta)
380	{
381	    DequantSwigluQuantKernel kernel;
382	    kernel.Init(x, weightScale, activationScale, quantScale, y, rowScale,
383	                M, N, H, blockM, usedCoreNum, tasksPerCore,
384	                swigluMode, activateLeft, clampLimit, gluAlpha, gluBeta);
385	    kernel.Process();
386	}
