27	// ---------------------------------------------------------------------------
28	// Tiling constants
29	// ---------------------------------------------------------------------------
30	
31	constexpr int32_t DEFAULT_BLOCK_M = 64;
32	constexpr int32_t DEFAULT_NUM_PHYSICAL_CORES = 20;
33	
34	// ---------------------------------------------------------------------------
35	// Host function
36	// ---------------------------------------------------------------------------
37	
38	namespace ascend_kernel {
39	
40	std::vector<at::Tensor> dequant_swiglu_quant(
41	    const at::Tensor &x,
42	    const at::Tensor &weightScale,
43	    const at::Tensor &activationScale,
44	    const at::Tensor &quantScale,
45	    int64_t swigluMode,
46	    int64_t activateLeft,
47	    double clampLimit,
48	    double gluAlpha,
49	    double gluBeta)
50	{
51	    // Input validation
52	    TORCH_CHECK(x.dim() == 2, "x must be [M, N]");
53	    TORCH_CHECK(x.scalar_type() == at::kInt, "x must be int32");
54	    TORCH_CHECK(weightScale.scalar_type() == at::kFloat,
55	                "weight_scale must be float32");
56	    TORCH_CHECK(activationScale.scalar_type() == at::kFloat,
57	                "activation_scale must be float32");
58	    TORCH_CHECK(x.is_contiguous(), "x must be contiguous");
59	    TORCH_CHECK(weightScale.is_contiguous(), "weight_scale must be contiguous");
60	    TORCH_CHECK(activationScale.is_contiguous(), "activation_scale must be contiguous");
61	
62	    int32_t M = static_cast<int32_t>(x.sizes()[0]);
63	    int32_t N = static_cast<int32_t>(x.sizes()[1]);
64	    int32_t H = N / 2;
65	
66	    // Convert quant_scale to float32 if needed
67	    at::Tensor qsFp32;
68	    if (quantScale.scalar_type() != at::kFloat) {
69	        qsFp32 = quantScale.to(at::kFloat).contiguous();
70	    } else {
71	        qsFp32 = quantScale.contiguous();
72	    }
73	
74	    // Tiling computation
