40	class DequantSwigluQuantKernel {
41	public:
42	    __aicore__ inline void Init(
43	        GM_ADDR x, GM_ADDR weightScale, GM_ADDR activationScale,
44	        GM_ADDR quantScale, GM_ADDR y, GM_ADDR rowScale,
45	        int32_t M, int32_t N, int32_t H,
46	        int32_t blockM, int32_t usedCoreNum, int32_t tasksPerCore,
47	        int64_t swigluMode, int64_t activateLeft,
48	        float clampLimit, float gluAlpha, float gluBeta)
49	    {
50	        M_ = M; N_ = N; H_ = H; blockM_ = blockM;
51	        usedCoreNum_ = usedCoreNum; tasksPerCore_ = tasksPerCore;
52	        swigluMode_ = static_cast<int32_t>(swigluMode);
53	        activateLeft_ = static_cast<int32_t>(activateLeft);
54	        clampLimit_ = clampLimit;
55	        gluAlpha_ = gluAlpha; gluBeta_ = gluBeta;
56	        inv127_ = 1.0f / 127.0f;
57	        vecNum_ = AscendC::GetSubBlockNum();
58	
59	        xGM_.SetGlobalBuffer(reinterpret_cast<__gm__ int32_t *>(x), static_cast<uint64_t>(M) * N);
60	        wsGM_.SetGlobalBuffer(reinterpret_cast<__gm__ float *>(weightScale), static_cast<uint64_t>(1) * N);
61	        asGM_.SetGlobalBuffer(reinterpret_cast<__gm__ float *>(activationScale), static_cast<uint64_t>(M));
62	        qsGM_.SetGlobalBuffer(reinterpret_cast<__gm__ float *>(quantScale), static_cast<uint64_t>(1) * H);
63	        yGM_.SetGlobalBuffer(reinterpret_cast<__gm__ int8_t *>(y), static_cast<uint64_t>(M) * H);
64	        rsGM_.SetGlobalBuffer(reinterpret_cast<__gm__ float *>(rowScale), static_cast<uint64_t>(M));
65	
66	        if ASCEND_IS_AIV { InitBuffers(); }
67	    }
68	
69	    __aicore__ inline void Process()
70	    {
71	        if ASCEND_IS_AIV {
72	            int32_t ci = AscendC::GetBlockIdx() / vecNum_;
73	            int32_t si = AscendC::GetSubBlockIdx();
74	            int32_t sr = blockM_ / vecNum_;
75	            int32_t mn = CeilDiv(M_, blockM_);
76	            for (int32_t li = 0; li < tasksPerCore_; ++li) {
77	                int32_t bx = ci * tasksPerCore_ + li;
78	                if (bx >= mn) continue;
79	                for (int32_t r = 0; r < sr; ++r) {
80	                    int32_t ri = bx * blockM_ + si * sr + r;
81	                    if (ri >= M_) continue;
82	                    ProcessRow(ri);
83	                }
84	            }
85	        }
86	    }
87	
88	private:
89	    __aicore__ inline void InitBuffers()
90	    {
91	        pipe_.InitBuffer(reduceTmp_, TILE_H * sizeof(float));
92	        pipe_.InitBuffer(scalarBuf_, sizeof(float));
93	        pipe_.InitBuffer(smoothBuf_, H_ * sizeof(float));
94	        pipe_.InitBuffer(xInQueue_, BUFFER_NUM, 2 * TILE_H * sizeof(int32_t));
95	        pipe_.InitBuffer(wsInQueue_, BUFFER_NUM, 2 * TILE_H * sizeof(float));
96	        pipe_.InitBuffer(fullDeq_, 2 * TILE_H * sizeof(float));
97	        pipe_.InitBuffer(yOutQueue_, BUFFER_NUM, TILE_H * sizeof(int8_t));
98	        pipe_.InitBuffer(dqFront_, TILE_H * sizeof(float));
99	        pipe_.InitBuffer(dqBack_, TILE_H * sizeof(float));
100	        pipe_.InitBuffer(swBuf_, TILE_H * sizeof(float));
101	        pipe_.InitBuffer(sigBuf_, TILE_H * sizeof(float));
102	        pipe_.InitBuffer(tmpBuf_, TILE_H * sizeof(float));
103	        pipe_.InitBuffer(qsBuf_, TILE_H * sizeof(float));
104	    }
105	
106	    // ===================================================================
107	    // Two-pass per row
108	    // ===================================================================
109	    __aicore__ inline void ProcessRow(int32_t rowIdx)
110	    {
111	        // Load activation_scale
112	        AscendC::LocalTensor<float> sb = scalarBuf_.Get<float>();
113	        {
114	            AscendC::DataCopyExtParams cp{1, sizeof(float), 0, 0, 0};
115	            AscendC::DataCopyPadExtParams<float> pp{false, 0, 0, 0.0f};
116	            AscendC::DataCopyPad(sb, asGM_[static_cast<uint64_t>(rowIdx)], cp, pp);
117	        }
118	        AscendC::PipeBarrier<PIPE_MTE2>();
119	        AscendC::PipeBarrier<PIPE_ALL>();
120	        float asVal = sb.GetValue(0);
121	
122	        // === Pass 1: compute SwiGLU + smooth quant, accumulate, track absmax ===
123	        float absmax = 0.0f;
124	        int32_t hTiles = CeilDiv(H_, TILE_H);
125	
126	        for (int32_t ht = 0; ht < hTiles; ++ht) {
127	            int32_t os = ht * TILE_H;
128	            int32_t co = (os + TILE_H <= H_) ? TILE_H : (H_ - os);
129	
130	            ComputeSwiGLU(rowIdx, os, co, asVal);
131	
132	            // Smooth quant: sw * qs
133	            AscendC::LocalTensor<float> sw = swBuf_.Get<float>();
134	            AscendC::LocalTensor<float> qs = qsBuf_.Get<float>();
135	            LoadGmPad(qs, qsGM_[static_cast<uint64_t>(os)], static_cast<uint32_t>(co));
136	            AscendC::PipeBarrier<PIPE_MTE2>();
137	            AscendC::PipeBarrier<PIPE_ALL>();
138	            AscendC::Mul(sw, sw, qs, co);
139	            AscendC::PipeBarrier<PIPE_V>();
140	
141	            // Accumulate into smoothBuf
142	            AscendC::LocalTensor<float> smDst = smoothBuf_.Get<float>();
143	            AscendC::DataCopy(smDst[os], sw, co);
144	            AscendC::PipeBarrier<PIPE_MTE2>();
145	            AscendC::PipeBarrier<PIPE_ALL>();
146	
147	            // Track absmax
148	            AscendC::LocalTensor<float> ab = tmpBuf_.Get<float>();
149	            AscendC::Abs(ab, sw, co);
150	            AscendC::PipeBarrier<PIPE_V>();
151	
152	            AscendC::LocalTensor<float> rb = reduceTmp_.Get<float>();
153	            AscendC::LocalTensor<float> am = scalarBuf_.Get<float>();
154	            AscendC::ReduceMax<float>(am, ab, rb, co);
155	            AscendC::PipeBarrier<PIPE_ALL>();
156	            float tm = am.GetValue(0);
157	            if (tm > absmax) absmax = tm;
158	        }
159	
160	        // Compute scales
161	        float sc = absmax * inv127_;
162	        float ssc = (sc > 0.0f) ? sc : 1.0f;
163	        float iSc = 1.0f / ssc;
164	
165	        // Write rowScale
166	        AscendC::LocalTensor<float> rsUb = scalarBuf_.Get<float>();
167	        rsUb.SetValue(0, ssc);
168	        AscendC::PipeBarrier<PIPE_V>();
169	        AscendC::GlobalTensor<float> rsDst = rsGM_[static_cast<uint64_t>(rowIdx)];
170	        AscendC::DataCopyExtParams rsCp{1, sizeof(float), 0, 0, 0};
171	        AscendC::DataCopyPad(rsDst, rsUb, rsCp);
172	        AscendC::PipeBarrier<PIPE_MTE2>();
173	        AscendC::PipeBarrier<PIPE_ALL>();
174	
175	        // === Pass 2: read smoothBuf, quantize, write output ===
176	        for (int32_t ht = 0; ht < hTiles; ++ht) {
177	            int32_t os = ht * TILE_H;
178	            int32_t co = (os + TILE_H <= H_) ? TILE_H : (H_ - os);
179	
180	            // Quantize from smoothBuf: read tile into swBuf_
181	            AscendC::LocalTensor<float> sm = swBuf_.Get<float>();
182	            AscendC::LocalTensor<float> smSrc = smoothBuf_.Get<float>();
183	            AscendC::DataCopy(sm, smSrc[os], co);
184	            AscendC::PipeBarrier<PIPE_MTE2>();
185	            AscendC::PipeBarrier<PIPE_ALL>();
186	
187	            // * invScale → round → clamp → cast to int8
188	            AscendC::Muls(sm, sm, iSc, co);
189	            AscendC::PipeBarrier<PIPE_V>();
190	            AscendC::Cast(sm, sm, AscendC::RoundMode::CAST_ROUND, co);
191	            AscendC::PipeBarrier<PIPE_V>();
192	
193	            // Clamp: use dqFront_ as clamp buffer (different from sm=swBuf_)
194	            AscendC::LocalTensor<float> cl = dqFront_.Get<float>();
195	            AscendC::Mins(cl, sm, 127.0f, co);
196	            AscendC::PipeBarrier<PIPE_V>();
197	            AscendC::Maxs(cl, cl, -128.0f, co);
198	            AscendC::PipeBarrier<PIPE_V>();
199	
200	            // Cast float→half→int8
201	            AscendC::LocalTensor<half> htH = dqBack_.Get<half>();
202	            AscendC::Cast(htH, cl, AscendC::RoundMode::CAST_NONE, co);
203	            AscendC::PipeBarrier<PIPE_V>();
204	
205	            AscendC::LocalTensor<int8_t> yo = yOutQueue_.AllocTensor<int8_t>();
206	            AscendC::Cast(yo, htH, AscendC::RoundMode::CAST_NONE, co);
207	            AscendC::PipeBarrier<PIPE_V>();
208	            yOutQueue_.EnQue(yo);
209	
210	            yo = yOutQueue_.DeQue<int8_t>();
211	            AscendC::GlobalTensor<int8_t> yDst = yGM_[static_cast<uint64_t>(rowIdx) * H_ + os];
212	            StoreUbPad(yDst, yo, static_cast<uint32_t>(co));
213	            yOutQueue_.FreeTensor(yo);
214	            AscendC::PipeBarrier<PIPE_MTE2>();
215	            AscendC::PipeBarrier<PIPE_ALL>();
216	        }
217	    }
