219	    // ===================================================================
220	    // SwiGLU computation (result in swBuf_)
221	    // ===================================================================
222	    __aicore__ inline void ComputeSwiGLU(
223	        int32_t rowIdx, int32_t outStart, int32_t curOut, float asVal)
224	    {
225	        if (swigluMode_ == 0) {
226	            // Mode 0: halves split + Swish
227	            // front = dequant(x[row, os:os+co]), back = dequant(x[row, H+os:H+os+co])
228	            DequantHalf(rowIdx, outStart, 0, curOut, asVal, dqFront_);
229	            DequantHalf(rowIdx, outStart, H_, curOut, asVal, dqBack_);
230	
231	            AscendC::LocalTensor<float> glu, lin;
232	            if (activateLeft_) {
233	                glu = dqFront_.Get<float>(); lin = dqBack_.Get<float>();
234	            } else {
235	                glu = dqBack_.Get<float>(); lin = dqFront_.Get<float>();
236	            }
237	
238	            // sigmoid(glu) = 1/(1+exp(-glu))
239	            AscendC::LocalTensor<float> sg = sigBuf_.Get<float>();
240	            AscendC::Muls(sg, glu, -1.0f, curOut);  AscendC::PipeBarrier<PIPE_V>();
241	            AscendC::Exp(sg, sg, curOut);            AscendC::PipeBarrier<PIPE_V>();
242	            AscendC::Adds(sg, sg, 1.0f, curOut);    AscendC::PipeBarrier<PIPE_V>();
243	            AscendC::Reciprocal(sg, sg, curOut);     AscendC::PipeBarrier<PIPE_V>();
244	
245	            // sw = lin * glu * sigmoid
246	            AscendC::LocalTensor<float> sw = swBuf_.Get<float>();
247	            AscendC::Mul(sw, glu, sg, curOut);  AscendC::PipeBarrier<PIPE_V>();
248	            AscendC::Mul(sw, sw, lin, curOut);  AscendC::PipeBarrier<PIPE_V>();
249	        } else {
250	            // Mode 1: even/odd split + gpt-oss
251	            // Load full tile (2*curOut elements of x and ws), dequant, then UB-level interleave
252	            int32_t n2 = curOut * 2;
253	            int32_t xOff = outStart * 2;
254	
255	            // Load full x tile contiguously
256	            AscendC::LocalTensor<int32_t> xi = xInQueue_.AllocTensor<int32_t>();
257	            LoadGmPad(xi, xGM_[static_cast<uint64_t>(rowIdx) * N_ + xOff],
258	                      static_cast<uint32_t>(n2));
259	            xInQueue_.EnQue(xi);
260	            xi = xInQueue_.DeQue<int32_t>();
261	
262	            // Load full ws tile contiguously
263	            AscendC::LocalTensor<float> wi = wsInQueue_.AllocTensor<float>();
264	            LoadGmPad(wi, wsGM_[static_cast<uint64_t>(xOff)],
265	                      static_cast<uint32_t>(n2));
266	            wsInQueue_.EnQue(wi);
267	            wi = wsInQueue_.DeQue<float>();
268	
269	            // Dequant: int32→float, *ws, *as  → result in fullDeq_
270	            AscendC::LocalTensor<float> dqAll = fullDeq_.Get<float>();
271	            AscendC::Cast(dqAll, xi, AscendC::RoundMode::CAST_NONE, n2);
272	            AscendC::PipeBarrier<PIPE_V>();
273	            AscendC::Mul(dqAll, dqAll, wi, n2);
274	            AscendC::PipeBarrier<PIPE_V>();
275	            AscendC::Muls(dqAll, dqAll, asVal, n2);
276	            AscendC::PipeBarrier<PIPE_V>();
277	
278	            wsInQueue_.FreeTensor(wi);
279	            xInQueue_.FreeTensor(xi);
280	
281	            // UB-level interleave: even elements → dqFront_ (glu), odd → dqBack_ (lin)
282	            AscendC::LocalTensor<float> glu = dqFront_.Get<float>();
283	            AscendC::LocalTensor<float> lin = dqBack_.Get<float>();
284	
285	            AscendC::DataCopyExtParams cpInter{
286	                static_cast<uint16_t>(curOut), static_cast<uint16_t>(sizeof(float)),
287	                static_cast<uint16_t>(2 * sizeof(float)), static_cast<uint16_t>(sizeof(float)), 0};
288	            AscendC::DataCopyPadExtParams<float> noPad{false, 0, 0, 0.0f};
289	            AscendC::DataCopy(glu, dqAll, cpInter, noPad);
290	            AscendC::PipeBarrier<PIPE_MTE2>();
291	            AscendC::PipeBarrier<PIPE_ALL>();
292	            AscendC::DataCopy(lin, dqAll[1], cpInter, noPad);
293	            AscendC::PipeBarrier<PIPE_MTE2>();
294	            AscendC::PipeBarrier<PIPE_ALL>();
295	
296	            // glu_c = min(glu, L)
297	            AscendC::LocalTensor<float> gc = tmpBuf_.Get<float>();
298	            AscendC::Mins(gc, glu, clampLimit_, curOut);  AscendC::PipeBarrier<PIPE_V>();
299	
300	            // lin_c = clamp(lin, -L, L)
301	            AscendC::Mins(lin, lin, clampLimit_, curOut);  AscendC::PipeBarrier<PIPE_V>();
302	            AscendC::Maxs(lin, lin, -clampLimit_, curOut); AscendC::PipeBarrier<PIPE_V>();
303	
304	            // sigmoid(alpha * glu_c) = 1/(1+exp(-alpha*glu_c))
305	            AscendC::LocalTensor<float> sg = sigBuf_.Get<float>();
306	            AscendC::Muls(sg, gc, gluAlpha_, curOut);  AscendC::PipeBarrier<PIPE_V>();
307	            AscendC::Muls(sg, sg, -1.0f, curOut);      AscendC::PipeBarrier<PIPE_V>();
308	            AscendC::Exp(sg, sg, curOut);               AscendC::PipeBarrier<PIPE_V>();
309	            AscendC::Adds(sg, sg, 1.0f, curOut);       AscendC::PipeBarrier<PIPE_V>();
310	            AscendC::Reciprocal(sg, sg, curOut);         AscendC::PipeBarrier<PIPE_V>();
311	
312	            // lin_c + beta
313	            AscendC::Adds(lin, lin, gluBeta_, curOut);  AscendC::PipeBarrier<PIPE_V>();
314	
315	            // sw = glu_c * sigmoid * (lin_c + beta)
316	            AscendC::LocalTensor<float> sw = swBuf_.Get<float>();
317	            AscendC::Mul(sw, gc, sg, curOut);   AscendC::PipeBarrier<PIPE_V>();
318	            AscendC::Mul(sw, sw, lin, curOut);  AscendC::PipeBarrier<PIPE_V>();
319	        }
320	    }
321	
322	    // Dequant contiguous half-tile: int32 load → Cast → Mul(ws) → Muls(as)
323	    __aicore__ inline void DequantHalf(
324	        int32_t rowIdx, int32_t outStart, int32_t colOffset,
325	        int32_t curOut, float asVal,
326	        AscendC::TBuf<AscendC::TPosition::VECCALC> &dqBuf)
327	    {
328	        AscendC::LocalTensor<int32_t> xi = xInQueue_.AllocTensor<int32_t>();
329	        LoadGmPad(xi, xGM_[static_cast<uint64_t>(rowIdx) * N_ + colOffset + outStart],
330	                  static_cast<uint32_t>(curOut));
331	        xInQueue_.EnQue(xi);
332	        xi = xInQueue_.DeQue<int32_t>();
333	
334	        AscendC::LocalTensor<float> wi = wsInQueue_.AllocTensor<float>();
335	        LoadGmPad(wi, wsGM_[static_cast<uint64_t>(colOffset + outStart)],
336	                  static_cast<uint32_t>(curOut));
337	        wsInQueue_.EnQue(wi);
338	        wi = wsInQueue_.DeQue<float>();
339	
340	        AscendC::LocalTensor<float> dq = dqBuf.Get<float>();
341	        AscendC::Cast(dq, xi, AscendC::RoundMode::CAST_NONE, curOut);
342	        AscendC::PipeBarrier<PIPE_V>();
343	        AscendC::Mul(dq, dq, wi, curOut);
344	        AscendC::PipeBarrier<PIPE_V>();
345	        AscendC::Muls(dq, dq, asVal, curOut);
346	        AscendC::PipeBarrier<PIPE_V>();
347	
348	        wsInQueue_.FreeTensor(wi);
349	        xInQueue_.FreeTensor(xi);
350	    }
351	
352	private:
353	    int32_t M_ = 0, N_ = 0, H_ = 0;
354	    int32_t blockM_ = 0, usedCoreNum_ = 0, tasksPerCore_ = 0;
355	    int32_t swigluMode_ = 0, activateLeft_ = 0;
356	    float clampLimit_ = 0, gluAlpha_ = 0, gluBeta_ = 0;
357	    float inv127_ = 0; int32_t vecNum_ = 0;
358	
359	    AscendC::GlobalTensor<int32_t> xGM_;
360	    AscendC::GlobalTensor<float> wsGM_, asGM_, qsGM_, rsGM_;
361	    AscendC::GlobalTensor<int8_t> yGM_;
362	
363	    AscendC::TPipe pipe_;
364	    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> xInQueue_, wsInQueue_;
365	    AscendC::TQue<AscendC::TPosition::VECOUT, BUFFER_NUM> yOutQueue_;
366	    AscendC::TBuf<AscendC::TPosition::VECCALC> reduceTmp_, scalarBuf_;
367	    AscendC::TBuf<AscendC::TPosition::VECCALC> smoothBuf_;
368	    AscendC::TBuf<AscendC::TPosition::VECCALC> dqFront_, dqBack_;
369	    AscendC::TBuf<AscendC::TPosition::VECCALC> swBuf_, sigBuf_, tmpBuf_, qsBuf_, fullDeq_;
370	};
371	
372	extern "C" __global__ __aicore__ void dequant_swiglu_quant(
373	    GM_ADDR x, GM_ADDR weightScale, GM_ADDR activationScale,
374	    GM_ADDR quantScale, GM_ADDR y, GM_ADDR rowScale,
375	    int32_t M, int32_t N, int32_t H,
376	    int32_t blockM, int32_t usedCoreNum, int32_t tasksPerCore,
377	    int64_t swigluMode, int64_t activateLeft,
