// AscendC DequantSwigluQuant kernel — fused dequant(int32->fp32) + SwiGLU + per-row int8 quant
// Two-pass per row:
//   Pass 1: compute SwiGLU per tile, smooth quant, accumulate to smoothBuf, track absmax.
//   Pass 2: read smoothBuf per tile, quantize (div by safeScale, round, clamp, cast), write output.

#include "kernel_operator.h"

constexpr int32_t BUFFER_NUM = 1;
constexpr int32_t TILE_H = 512;

__aicore__ inline int32_t CeilDiv(int32_t a, int32_t b)
{
    if (b == 0) { return 0; }
    return (a + b - 1) / b;
}

template <typename T>
__aicore__ inline void LoadGmPad(
    AscendC::LocalTensor<T> &dst, AscendC::GlobalTensor<T> src, uint32_t count)
{
    AscendC::DataCopyExtParams cp{1, count * static_cast<uint32_t>(sizeof(T)), 0, 0, 0};
    AscendC::DataCopyPadExtParams<T> pp{true, 0, 0, static_cast<T>(0)};
    AscendC::DataCopyPad(dst, src, cp, pp);
}

template <typename T>
__aicore__ inline void StoreUbPad(
    AscendC::GlobalTensor<T> dst, AscendC::LocalTensor<T> &src, uint32_t count)
{
    AscendC::DataCopyExtParams cp{1, count * static_cast<uint32_t>(sizeof(T)), 0, 0, 0};
    AscendC::DataCopyPad(dst, src, cp);
}

template <typename T>
__aicore__ inline void LoadGmStridedE2(
    AscendC::LocalTensor<T> &dst, AscendC::GlobalTensor<T> src, uint32_t count)
{
    AscendC::DataCopyExtParams cp{
        static_cast<uint16_t>(count), static_cast<uint16_t>(sizeof(T)),
        static_cast<uint16_t>(2 * sizeof(T)), static_cast<uint16_t>(sizeof(T)), 0};
    AscendC::DataCopyPadExtParams<T> pp{false, 0, 0, static_cast<T>(0)};
    AscendC::DataCopyPad(dst, src, cp, pp);
}

class DequantSwigluQuantKernel {
public:
    __aicore__ inline void Init(
        GM_ADDR x, GM_ADDR weightScale, GM_ADDR activationScale,
        GM_ADDR quantScale, GM_ADDR y, GM_ADDR rowScale,
        int32_t M, int32_t N, int32_t H,
        int32_t blockM, int32_t usedCoreNum, int32_t tasksPerCore,
        int64_t swigluMode, int64_t activateLeft,
        float clampLimit, float gluAlpha, float gluBeta)
    {
        M_ = M; N_ = N; H_ = H; blockM_ = blockM;
        usedCoreNum_ = usedCoreNum; tasksPerCore_ = tasksPerCore;
        swigluMode_ = static_cast<int32_t>(swigluMode);
        activateLeft_ = static_cast<int32_t>(activateLeft);
        clampLimit_ = clampLimit;
        gluAlpha_ = gluAlpha; gluBeta_ = gluBeta;
        inv127_ = 1.0f / 127.0f;
        vecNum_ = AscendC::GetSubBlockNum();

        xGM_.SetGlobalBuffer(reinterpret_cast<__gm__ int32_t *>(x), static_cast<uint64_t>(M) * N);
        wsGM_.SetGlobalBuffer(reinterpret_cast<__gm__ float *>(weightScale), static_cast<uint64_t>(1) * N);
        asGM_.SetGlobalBuffer(reinterpret_cast<__gm__ float *>(activationScale), static_cast<uint64_t>(M));
        qsGM_.SetGlobalBuffer(reinterpret_cast<__gm__ float *>(quantScale), static_cast<uint64_t>(1) * H);
        yGM_.SetGlobalBuffer(reinterpret_cast<__gm__ int8_t *>(y), static_cast<uint64_t>(M) * H);
        rsGM_.SetGlobalBuffer(reinterpret_cast<__gm__ float *>(rowScale), static_cast<uint64_t>(M));

        if ASCEND_IS_AIV { InitBuffers(); }
    }

    __aicore__ inline void Process()
    {
        if ASCEND_IS_AIV {
            int32_t ci = AscendC::GetBlockIdx() / vecNum_;
            int32_t si = AscendC::GetSubBlockIdx();
            int32_t sr = blockM_ / vecNum_;
            int32_t mn = CeilDiv(M_, blockM_);
            for (int32_t li = 0; li < tasksPerCore_; ++li) {
                int32_t bx = ci * tasksPerCore_ + li;
                if (bx >= mn) continue;
                for (int32_t r = 0; r < sr; ++r) {
                    int32_t ri = bx * blockM_ + si * sr + r;
                    if (ri >= M_) continue;
                    ProcessRow(ri);
                }
            }
        }
    }

private:
    __aicore__ inline void InitBuffers()
    {
        pipe_.InitBuffer(reduceTmp_, TILE_H * sizeof(float));
        pipe_.InitBuffer(scalarBuf_, sizeof(float));
        pipe_.InitBuffer(smoothBuf_, H_ * sizeof(float));
        pipe_.InitBuffer(xInQueue_, BUFFER_NUM, 2 * TILE_H * sizeof(int32_t));
        pipe_.InitBuffer(wsInQueue_, BUFFER_NUM, 2 * TILE_H * sizeof(float));
        pipe_.InitBuffer(fullDeq_, 2 * TILE_H * sizeof(float));
        pipe_.InitBuffer(yOutQueue_, BUFFER_NUM, TILE_H * sizeof(int8_t));
        pipe_.InitBuffer(dqFront_, TILE_H * sizeof(float));
        pipe_.InitBuffer(dqBack_, TILE_H * sizeof(float));
        pipe_.InitBuffer(swBuf_, TILE_H * sizeof(float));
        pipe_.InitBuffer(sigBuf_, TILE_H * sizeof(float));
        pipe_.InitBuffer(tmpBuf_, TILE_H * sizeof(float));
        pipe_.InitBuffer(qsBuf_, TILE_H * sizeof(float));
    }

    // ===================================================================
    // Two-pass per row
    // ===================================================================
    __aicore__ inline void ProcessRow(int32_t rowIdx)
    {
        // Load activation_scale
        AscendC::LocalTensor<float> sb = scalarBuf_.Get<float>();
        {
            AscendC::DataCopyExtParams cp{1, sizeof(float), 0, 0, 0};
            AscendC::DataCopyPadExtParams<float> pp{false, 0, 0, 0.0f};
            AscendC::DataCopyPad(sb, asGM_[static_cast<uint64_t>(rowIdx)], cp, pp);
        }
        AscendC::PipeBarrier<PIPE_MTE2>();
        AscendC::PipeBarrier<PIPE_ALL>();
        float asVal = sb.GetValue(0);

        // === Pass 1: compute SwiGLU + smooth quant, accumulate, track absmax ===
        float absmax = 0.0f;
        int32_t hTiles = CeilDiv(H_, TILE_H);

        for (int32_t ht = 0; ht < hTiles; ++ht) {
            int32_t os = ht * TILE_H;
            int32_t co = (os + TILE_H <= H_) ? TILE_H : (H_ - os);

            ComputeSwiGLU(rowIdx, os, co, asVal);

            // Smooth quant: sw * qs
            AscendC::LocalTensor<float> sw = swBuf_.Get<float>();
            AscendC::LocalTensor<float> qs = qsBuf_.Get<float>();
            LoadGmPad(qs, qsGM_[static_cast<uint64_t>(os)], static_cast<uint32_t>(co));
            AscendC::PipeBarrier<PIPE_MTE2>();
            AscendC::PipeBarrier<PIPE_ALL>();
            AscendC::Mul(sw, sw, qs, co);
            AscendC::PipeBarrier<PIPE_V>();

            // Accumulate into smoothBuf
            AscendC::LocalTensor<float> smDst = smoothBuf_.Get<float>();
            AscendC::DataCopy(smDst[os], sw, co);
            AscendC::PipeBarrier<PIPE_MTE2>();
            AscendC::PipeBarrier<PIPE_ALL>();

            // Track absmax
            AscendC::LocalTensor<float> ab = tmpBuf_.Get<float>();
            AscendC::Abs(ab, sw, co);
            AscendC::PipeBarrier<PIPE_V>();

            AscendC::LocalTensor<float> rb = reduceTmp_.Get<float>();
            AscendC::LocalTensor<float> am = scalarBuf_.Get<float>();
            AscendC::ReduceMax<float>(am, ab, rb, co);
            AscendC::PipeBarrier<PIPE_ALL>();
            float tm = am.GetValue(0);
            if (tm > absmax) absmax = tm;
        }

        // Compute scales
        float sc = absmax * inv127_;
        float ssc = (sc > 0.0f) ? sc : 1.0f;
        float iSc = 1.0f / ssc;

        // Write rowScale
        AscendC::LocalTensor<float> rsUb = scalarBuf_.Get<float>();
        rsUb.SetValue(0, ssc);
        AscendC::PipeBarrier<PIPE_V>();
        AscendC::GlobalTensor<float> rsDst = rsGM_[static_cast<uint64_t>(rowIdx)];
        AscendC::DataCopyExtParams rsCp{1, sizeof(float), 0, 0, 0};
        AscendC::DataCopyPad(rsDst, rsUb, rsCp);
        AscendC::PipeBarrier<PIPE_MTE2>();
        AscendC::PipeBarrier<PIPE_ALL>();

        // === Pass 2: read smoothBuf, quantize, write output ===
        for (int32_t ht = 0; ht < hTiles; ++ht) {
            int32_t os = ht * TILE_H;
            int32_t co = (os + TILE_H <= H_) ? TILE_H : (H_ - os);

            // Quantize from smoothBuf: read tile into swBuf_
            AscendC::LocalTensor<float> sm = swBuf_.Get<float>();
            AscendC::LocalTensor<float> smSrc = smoothBuf_.Get<float>();
            AscendC::DataCopy(sm, smSrc[os], co);
            AscendC::PipeBarrier<PIPE_MTE2>();
            AscendC::PipeBarrier<PIPE_ALL>();

            // * invScale → round → clamp → cast to int8
            AscendC::Muls(sm, sm, iSc, co);
            AscendC::PipeBarrier<PIPE_V>();
            AscendC::Cast(sm, sm, AscendC::RoundMode::CAST_ROUND, co);
            AscendC::PipeBarrier<PIPE_V>();

            // Clamp: use dqFront_ as clamp buffer
            AscendC::LocalTensor<float> cl = dqFront_.Get<float>();
            AscendC::Mins(cl, sm, 127.0f, co);
            AscendC::PipeBarrier<PIPE_V>();
            AscendC::Maxs(cl, cl, -128.0f, co);
            AscendC::PipeBarrier<PIPE_V>();

            // Cast float→half→int8
            AscendC::LocalTensor<half> htH = dqBack_.Get<half>();
            AscendC::Cast(htH, cl, AscendC::RoundMode::CAST_NONE, co);
            AscendC::PipeBarrier<PIPE_V>();

            AscendC::LocalTensor<int8_t> yo = yOutQueue_.AllocTensor<int8_t>();
            AscendC::Cast(yo, htH, AscendC::RoundMode::CAST_NONE, co);
            AscendC::PipeBarrier<PIPE_V>();
            yOutQueue_.EnQue(yo);

            yo = yOutQueue_.DeQue<int8_t>();
            AscendC::GlobalTensor<int8_t> yDst = yGM_[static_cast<uint64_t>(rowIdx) * H_ + os];
            StoreUbPad(yDst, yo, static_cast<uint32_t>(co));
            yOutQueue_.FreeTensor(yo);
            AscendC::PipeBarrier<PIPE_MTE2>();
            AscendC::PipeBarrier<PIPE_ALL>();
        }
    }

    // ===================================================================
    // SwiGLU computation (result in swBuf_)
    // ===================================================================
    __aicore__ inline void ComputeSwiGLU(
        int32_t rowIdx, int32_t outStart, int32_t curOut, float asVal)
    {
        if (swigluMode_ == 0) {
            // Mode 0: halves split + Swish
            DequantHalf(rowIdx, outStart, 0, curOut, asVal, dqFront_);
            DequantHalf(rowIdx, outStart, H_, curOut, asVal, dqBack_);

            AscendC::LocalTensor<float> glu, lin;
            if (activateLeft_) {
                glu = dqFront_.Get<float>(); lin = dqBack_.Get<float>();
            } else {
                glu = dqBack_.Get<float>(); lin = dqFront_.Get<float>();
            }

            // sigmoid(glu) = 1/(1+exp(-glu))
            AscendC::LocalTensor<float> sg = sigBuf_.Get<float>();
            AscendC::Muls(sg, glu, -1.0f, curOut);  AscendC::PipeBarrier<PIPE_V>();
            AscendC::Exp(sg, sg, curOut);            AscendC::PipeBarrier<PIPE_V>();
            AscendC::Adds(sg, sg, 1.0f, curOut);    AscendC::PipeBarrier<PIPE_V>();
            AscendC::Reciprocal(sg, sg, curOut);     AscendC::PipeBarrier<PIPE_V>();

            // sw = lin * glu * sigmoid
            AscendC::LocalTensor<float> sw = swBuf_.Get<float>();
            AscendC::Mul(sw, glu, sg, curOut);  AscendC::PipeBarrier<PIPE_V>();
            AscendC::Mul(sw, sw, lin, curOut);  AscendC::PipeBarrier<PIPE_V>();
        } else {
            // Mode 1: even/odd split + gpt-oss
            int32_t is = outStart * 2;
            DequantStrided(rowIdx, is, curOut, asVal, dqFront_);
            DequantStrided(rowIdx, is + 1, curOut, asVal, dqBack_);

            AscendC::LocalTensor<float> glu = dqFront_.Get<float>();
            AscendC::LocalTensor<float> lin = dqBack_.Get<float>();

            // glu_c = min(glu, L)
            AscendC::LocalTensor<float> gc = tmpBuf_.Get<float>();
            AscendC::Mins(gc, glu, clampLimit_, curOut);  AscendC::PipeBarrier<PIPE_V>();

            // lin_c = clamp(lin, -L, L)
            AscendC::Mins(lin, lin, clampLimit_, curOut);  AscendC::PipeBarrier<PIPE_V>();
            AscendC::Maxs(lin, lin, -clampLimit_, curOut); AscendC::PipeBarrier<PIPE_V>();

            // sigmoid(alpha * glu_c)
            AscendC::LocalTensor<float> sg = sigBuf_.Get<float>();
            AscendC::Muls(sg, gc, gluAlpha_, curOut);  AscendC::PipeBarrier<PIPE_V>();
            AscendC::Muls(sg, sg, -1.0f, curOut);      AscendC::PipeBarrier<PIPE_V>();
            AscendC::Exp(sg, sg, curOut);               AscendC::PipeBarrier<PIPE_V>();
            AscendC::Adds(sg, sg, 1.0f, curOut);       AscendC::PipeBarrier<PIPE_V>();
            AscendC::Reciprocal(sg, sg, curOut);         AscendC::PipeBarrier<PIPE_V>();

            // lin_c + beta
            AscendC::Adds(lin, lin, gluBeta_, curOut);  AscendC::PipeBarrier<PIPE_V>();

            // sw = glu_c * sigmoid * (lin_c + beta)
            AscendC::LocalTensor<float> sw = swBuf_.Get<float>();
            AscendC::Mul(sw, gc, sg, curOut);   AscendC::PipeBarrier<PIPE_V>();
            AscendC::Mul(sw, sw, lin, curOut);  AscendC::PipeBarrier<PIPE_V>();
        }
    }

    // Dequant contiguous half-tile: int32 load → Cast → Mul(ws) → Muls(as)
    __aicore__ inline void DequantHalf(
        int32_t rowIdx, int32_t outStart, int32_t colOffset,
        int32_t curOut, float asVal,
        AscendC::TBuf<AscendC::TPosition::VECCALC> &dqBuf)
    {
        AscendC::LocalTensor<int32_t> xi = xInQueue_.AllocTensor<int32_t>();
        LoadGmPad(xi, xGM_[static_cast<uint64_t>(rowIdx) * N_ + colOffset + outStart],
                  static_cast<uint32_t>(curOut));
        xInQueue_.EnQue(xi);
        xi = xInQueue_.DeQue<int32_t>();

        AscendC::LocalTensor<float> wi = wsInQueue_.AllocTensor<float>();
        LoadGmPad(wi, wsGM_[static_cast<uint64_t>(colOffset + outStart)],
                  static_cast<uint32_t>(curOut));
        wsInQueue_.EnQue(wi);
        wi = wsInQueue_.DeQue<float>();

        AscendC::LocalTensor<float> dq = dqBuf.Get<float>();
        AscendC::Cast(dq, xi, AscendC::RoundMode::CAST_NONE, curOut);
        AscendC::PipeBarrier<PIPE_V>();
        AscendC::Mul(dq, dq, wi, curOut);
        AscendC::PipeBarrier<PIPE_V>();
        AscendC::Muls(dq, dq, asVal, curOut);
        AscendC::PipeBarrier<PIPE_V>();

        wsInQueue_.FreeTensor(wi);
        xInQueue_.FreeTensor(xi);
    }

    // Dequant strided (every 2nd element): int32 load → Cast → Mul(ws) → Muls(as)
    __aicore__ inline void DequantStrided(
        int32_t rowIdx, int32_t inStart, int32_t curOut, float asVal,
        AscendC::TBuf<AscendC::TPosition::VECCALC> &dqBuf)
    {
        AscendC::LocalTensor<int32_t> xi = xInQueue_.AllocTensor<int32_t>();
        LoadGmStridedE2(xi, xGM_[static_cast<uint64_t>(rowIdx) * N_ + inStart],
                        static_cast<uint32_t>(curOut));
        xInQueue_.EnQue(xi);
        xi = xInQueue_.DeQue<int32_t>();

        AscendC::LocalTensor<float> wi = wsInQueue_.AllocTensor<float>();
        LoadGmStridedE2(wi, wsGM_[static_cast<uint64_t>(inStart)],
                        static_cast<uint32_t>(curOut));
        wsInQueue_.EnQue(wi);
        wi = wsInQueue_.DeQue<float>();

        AscendC::LocalTensor<float> dq = dqBuf.Get<float>();
        AscendC::Cast(dq, xi, AscendC::RoundMode::CAST_NONE, curOut);
        AscendC::PipeBarrier<PIPE_V>();
        AscendC::Mul(dq, dq, wi, curOut);
        AscendC::PipeBarrier<PIPE_V>();
        AscendC::Muls(dq, dq, asVal, curOut);
        AscendC::PipeBarrier<PIPE_V>();

        wsInQueue_.FreeTensor(wi);
        xInQueue_.FreeTensor(xi);
    }

private:
    int32_t M_ = 0, N_ = 0, H_ = 0;
    int32_t blockM_ = 0, usedCoreNum_ = 0, tasksPerCore_ = 0;
    int32_t swigluMode_ = 0, activateLeft_ = 0;
    float clampLimit_ = 0, gluAlpha_ = 0, gluBeta_ = 0;
    float inv127_ = 0; int32_t vecNum_ = 0;

    AscendC::GlobalTensor<int32_t> xGM_;
    AscendC::GlobalTensor<float> wsGM_, asGM_, qsGM_, rsGM_;
    AscendC::GlobalTensor<int8_t> yGM_;

    AscendC::TPipe pipe_;
    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> xInQueue_, wsInQueue_;
    AscendC::TQue<AscendC::TPosition::VECOUT, BUFFER_NUM> yOutQueue_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> reduceTmp_, scalarBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> smoothBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> dqFront_, dqBack_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> swBuf_, sigBuf_, tmpBuf_, qsBuf_, fullDeq_;
};

extern "C" __global__ __aicore__ void dequant_swiglu_quant(
    GM_ADDR x, GM_ADDR weightScale, GM_ADDR activationScale,
    GM_ADDR quantScale, GM_ADDR y, GM_ADDR rowScale,
    int32_t M, int32_t N, int32_t H,
    int32_t blockM, int32_t usedCoreNum, int32_t tasksPerCore,
    int64_t swigluMode, int64_t activateLeft,
    float clampLimit, float gluAlpha, float gluBeta)
{
    DequantSwigluQuantKernel kernel;
    kernel.Init(x, weightScale, activationScale, quantScale, y, rowScale,
                M, N, H, blockM, usedCoreNum, tasksPerCore,
                swigluMode, activateLeft, clampLimit, gluAlpha, gluBeta);
